import React, { useEffect, useState, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import api, { getImageUrl } from '../services/api';
import { motion, AnimatePresence } from 'framer-motion';
import { Link } from 'react-router-dom';
import styles from './UserDashboard.module.css';

const UserDashboard = () => {
  const { user, setUser, notifications, clearNotifications } = useAuth();
  const [activeTab, setActiveTab] = useState('profile');
  const [purchases, setPurchases] = useState([]);
  const [testDrives, setTestDrives] = useState([]);
  const [loans, setLoans] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [loading, setLoading] = useState(true);
  
  // Состояния для печати чеков
  const [printingId, setPrintingId] = useState(null);
  
  // Состояния для отзывов по тест-драйвам
  const [showReviewModal, setShowReviewModal] = useState(false);
  const [activeReviewTd, setActiveReviewTd] = useState(null);
  const [reviewRating, setReviewRating] = useState(5);
  const [reviewComment, setReviewComment] = useState('');
  const [hoverRating, setHoverRating] = useState(null);
  
  // Состояния для просмотра комментариев
  const [showViewModal, setShowViewModal] = useState(false);
  const [viewComment, setViewComment] = useState(null);
  
  // Форма редактирования профиля
  const [profileForm, setProfileForm] = useState({
    full_name: user?.full_name || '',
    phone: user?.phone || '',
  });
  const [profileMessage, setProfileMessage] = useState('');

  // Загрузка всех необходимых данных пользователя
  const fetchDashboardData = useCallback(async () => {
    if (!user) return;
    try {
      setLoading(true);
      const [purchasesRes, testDrivesRes, loansRes, favoritesRes] = await Promise.all([
        api.get('/purchases/my').catch(() => ({ data: [] })),
        api.get('/testdrives/my').catch(() => ({ data: [] })),
        api.get('/loans/my').catch(() => ({ data: [] })),
        api.get('/favorites/my').catch(() => ({ data: [] }))
      ]);
      
      setPurchases(purchasesRes.data);
      setTestDrives(testDrivesRes.data);
      setLoans(loansRes.data);
      setFavorites(favoritesRes.data);
    } catch (error) {
      console.error("Ошибка при получении данных личного кабинета:", error);
    } finally {
      setLoading(false);
    }
  }, [user]);

  useEffect(() => {
    fetchDashboardData();
  }, [fetchDashboardData]);

  // Обработка обновления профиля
  const handleProfileUpdate = async (e) => {
    e.preventDefault();
    try {
      const res = await api.put('/auth/profile', profileForm);
      setUser(res.data);
      setProfileMessage('Профиль успешно обновлен!');
      setTimeout(() => setProfileMessage(''), 4000);
    } catch (error) {
      setProfileMessage('Ошибка при обновлении профиля.');
      console.error(error);
    }
  };

  // Запуск печати индивидуального чека
  const handlePrintReceipt = (purchase) => {
    setPrintingId(purchase.id);
    // Небольшая задержка, чтобы React успел отрендерить скрытый блок печати
    setTimeout(() => {
      window.print();
      setPrintingId(null);
    }, 150);
  };

  // Открытие модального окна отзыва
  const openReviewModal = (tdId) => {
    setActiveReviewTd(tdId);
    setReviewRating(5);
    setReviewComment('');
    setShowReviewModal(true);
  };

  // Отправка отзыва на сервер
  const handleReviewSubmit = async (e) => {
    e.preventDefault();
    try {
      await api.post('/testdrives/review', {
        test_drive_id: activeReviewTd,
        rating: reviewRating,
        comment: reviewComment
      });
      setShowReviewModal(false);
      setActiveReviewTd(null);
      // Обновляем список тест-драйвов, чтобы увидеть изменения
      const tdRes = await api.get('/testdrives/my');
      setTestDrives(tdRes.data);
    } catch (error) {
      console.error("Ошибка при отправке отзыва:", error);
      alert("Не удалось отправить отзыв.");
    }
  };

  // Открытие модального окна просмотра комментария администрации
  const openViewCommentModal = (title, subtitle, commentText) => {
    setViewComment({ title, subtitle, comment: commentText });
    setShowViewModal(true);
  };

  if (loading) {
    return <div className={styles.loading}>Загрузка данных личного кабинета...</div>;
  }

  return (
    <motion.div 
      className={styles.container}
      initial={{ opacity: 0, y: -10 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
    >
      <h1 className={styles.title}>Личный кабинет</h1>
      
      {/* Навигационные вкладки */}
      <div className={styles.tabs}>
        <button className={`${styles.tab} ${activeTab === 'profile' ? styles.active : ''}`} onClick={() => setActiveTab('profile')}>Профиль</button>
        <button className={`${styles.tab} ${activeTab === 'purchases' ? styles.active : ''}`} onClick={() => setActiveTab('purchases')}>Покупки ({purchases.length})</button>
        <button className={`${styles.tab} ${activeTab === 'testdrives' ? styles.active : ''}`} onClick={() => setActiveTab('testdrives')}>Тест-драйвы ({testDrives.length})</button>
        <button className={`${styles.tab} ${activeTab === 'loans' ? styles.active : ''}`} onClick={() => setActiveTab('loans')}>Кредиты ({loans.length})</button>
        <button className={`${styles.tab} ${activeTab === 'favorites' ? styles.active : ''}`} onClick={() => setActiveTab('favorites')}>Избранное ({favorites.length})</button>
      </div>

      {/* Содержимое вкладок */}
      <div className={styles.tabContent}>
        
        {/* ВКЛАДКА: ПРОФИЛЬ */}
        {activeTab === 'profile' && (
          <div className={styles.profileSection}>
            <div className={styles.gridTwoColumns}>
              <form onSubmit={handleProfileUpdate} className={styles.formCard}>
                <h3>Личные данные</h3>
                <div className={styles.inputGroup}>
                  <label>Электронная почта (логин)</label>
                  <input type="email" value={user?.email || ''} disabled className={styles.disabledInput} />
                </div>
                <div className={styles.inputGroup}>
                  <label>ФИО</label>
                  <input 
                    type="text" 
                    value={profileForm.full_name} 
                    onChange={(e) => setProfileForm({ ...profileForm, full_name: e.target.value })} 
                    placeholder="Иванов Иван Иванович"
                    required 
                  />
                </div>
                <div className={styles.inputGroup}>
                  <label>Телефон</label>
                  <input 
                    type="tel" 
                    value={profileForm.phone} 
                    onChange={(e) => setProfileForm({ ...profileForm, phone: e.target.value })} 
                    placeholder="+7 (999) 123-45-67" 
                    required
                  />
                </div>
                <button type="submit" className={styles.submitBtn}>Сохранить изменения</button>
                {profileMessage && <p className={styles.formMessage}>{profileMessage}</p>}
              </form>

              <div className={styles.notificationsCard}>
                <div className={styles.notificationsHeader}>
                  <h3>Уведомления</h3>
                  {notifications && notifications.length > 0 && (
                    <button className={styles.clearBtn} onClick={clearNotifications}>Очистить все</button>
                  )}
                </div>
                <div className={styles.notificationsList}>
                  {notifications && notifications.length > 0 ? (
                    notifications.map((notif) => (
                      <div key={notif.id} className={styles.notificationItem}>
                        <p>{notif.message}</p>
                        <span className={styles.notifTime}>{new Date(notif.id).toLocaleTimeString()}</span>
                      </div>
                    ))
                  ) : (
                    <p className={styles.emptyText}>У вас нет новых уведомлений.</p>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}

        {/* ВКЛАДКА: ПОКУПКИ */}
        {activeTab === 'purchases' && (
          <div className={styles.cardsGrid}>
            {purchases.length > 0 ? (
              purchases.map((purchase) => (
                <div key={purchase.id} className={styles.card}>
                  <img src={getImageUrl(purchase.car?.image_url)} alt={`${purchase.car?.brand} ${purchase.car?.model}`} className={styles.cardImage} />
                  <div className={styles.cardContent}>
                    <h4>{purchase.car?.brand} {purchase.car?.model}</h4>
                    <p className={styles.carMeta}>Год выпуска: {purchase.car?.year}</p>
                    <div className={styles.priceTag}>{(purchase.price || purchase.car?.price)?.toLocaleString()} ₽</div>
                    <p className={styles.purchaseDate}>Дата покупки: {new Date(purchase.created_at).toLocaleDateString()}</p>
                    <button className={styles.printBtn} onClick={() => handlePrintReceipt(purchase)}>
                      🖨️ Распечатать чек
                    </button>
                  </div>
                </div>
              ))
            ) : (
              <p className={styles.emptyText}>История покупок пуста.</p>
            )}
          </div>
        )}

        {/* ВКЛАДКА: ТЕСТ-ДРАЙВЫ */}
        {activeTab === 'testdrives' && (
          <div className={styles.cardsGrid}>
            {testDrives.length > 0 ? (
              testDrives.map((td) => (
                <div key={td.id} className={styles.card}>
                  <div className={styles.cardContent}>
                    <h4>{td.car?.brand} {td.car?.model}</h4>
                    <p className={styles.infoRow}><strong>Дата и время:</strong> {new Date(td.preferred_date).toLocaleString()}</p>
                    <p className={styles.infoRow}><strong>Телефон:</strong> {td.phone}</p>
                    {td.message && <p className={styles.infoRow}><strong>Ваше сообщение:</strong> {td.message}</p>}
                    
                    <div className={styles.statusWrapper}>
                      <span className={`${styles.statusBadge} ${styles[td.status]}`}>
                        {td.status === 'pending' && '⏳ В ожидании'}
                        {td.status === 'approved' && '✅ Одобрен'}
                        {td.status === 'rejected' && '❌ Отклонен'}
                      </span>
                    </div>

                    {/* Кнопки действий */}
                    <div className={styles.actionsContainer}>
                      {td.admin_comment && (
                        <button 
                          className={styles.secondaryActionBtn}
                          onClick={() => openViewCommentModal(
                            `Комментарий к тест-драйву`,
                            `${td.car?.brand} ${td.car?.model} (${new Date(td.preferred_date).toLocaleDateString()})`,
                            td.admin_comment
                          )}
                        >
                          👁️ Ответ автосалона
                        </button>
                      )}
                      
                      {td.status === 'approved' && !td.review_left && (
                        <button className={styles.primaryActionBtn} onClick={() => openReviewModal(td.id)}>
                          ⭐ Оставить отзыв
                        </button>
                      )}
                      {td.review_left && (
                        <span className={styles.completedBadge}>Отзыв оставлен</span>
                      )}
                    </div>
                  </div>
                </div>
              ))
            ) : (
              <p className={styles.emptyText}>Вы еще не записывались на тест-драйвы.</p>
            )}
          </div>
        )}

        {/* ВКЛАДКА: КРЕДИТЫ */}
        {activeTab === 'loans' && (
          <div className={styles.cardsGrid}>
            {loans.length > 0 ? (
              loans.map((loan) => (
                <div key={loan.id} className={styles.card}>
                  <div className={styles.cardContent}>
                    <h4>Кредит на {loan.car?.brand} {loan.car?.model}</h4>
                    <div className={styles.loanDetails}>
                      <p>Сумма кредита: <strong>{loan.amount?.toLocaleString()} ₽</strong></p>
                      <p>Срок: <strong>{loan.term_months} мес.</strong></p>
                      <p>Ставка: <strong>{loan.interest_rate}%</strong></p>
                      <p>Ежемесячный платёж: <strong className={styles.highlightText}>{loan.monthly_payment?.toLocaleString()} ₽</strong></p>
                    </div>
                    
                    <div className={styles.statusWrapper}>
                      <span className={`${styles.statusBadge} ${styles[loan.status]}`}>
                        {loan.status === 'calculated' && '📊 Расчитан'}
                        {loan.status === 'pending' && '⏳ На рассмотрении'}
                        {loan.status === 'approved' && '✅ Кредит одобрен'}
                        {loan.status === 'rejected' && '❌ Отклонен'}
                      </span>
                    </div>

                    {loan.admin_comment && (
                      <button 
                        className={styles.secondaryActionBtn} 
                        onClick={() => openViewCommentModal(
                          `Решение по кредитной заявке`,
                          `Сумма: ${loan.amount?.toLocaleString()} ₽ на ${loan.car?.brand} ${loan.car?.model}`,
                          loan.admin_comment
                        )}
                      >
                        👁️ Подробнее от банка
                      </button>
                    )}
                  </div>
                </div>
              ))
            ) : (
              <p className={styles.emptyText}>У вас нет оформленных заявок на кредит.</p>
            )}
          </div>
        )}

        {/* ВКЛАДКА: ИЗБРАННОЕ */}
        {activeTab === 'favorites' && (
          <div className={styles.cardsGrid}>
            {favorites.length > 0 ? (
              favorites.map((fav) => (
                <div key={fav.id} className={styles.card}>
                  <img src={getImageUrl(fav.image_url)} alt={`${fav.brand} ${fav.model}`} className={styles.cardImage} />
                  <div className={styles.cardContent}>
                    <h4>{fav.brand} {fav.model}</h4>
                    <p className={styles.carMeta}>Год: {fav.year} | Тип: {fav.body_type}</p>
                    <div className={styles.priceTag}>{fav.price?.toLocaleString()} ₽</div>
                    <Link to={`/catalog/${fav.id}`} className={styles.viewDetailsLink}>
                      Перейти к автомобилю →
                    </Link>
                  </div>
                </div>
              ))
            ) : (
              <p className={styles.emptyText}>Список избранного пуст.</p>
            )}
          </div>
        )}

      </div>

      {/* МОДАЛЬНЫЕ ОКНА НА БАЗЕ FRAMER MOTION */}
      <AnimatePresence>
        
        {/* 1. Модальное окно создания отзыва */}
        {showReviewModal && (
          <motion.div 
            className={styles.modalOverlay}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setShowReviewModal(false)}
          >
            <motion.div 
              className={styles.modal}
              initial={{ scale: 0.9, opacity: 0, y: 20 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              exit={{ scale: 0.9, opacity: 0, y: 20 }}
              onClick={(e) => e.stopPropagation()}
            >
              <button className={styles.modalClose} onClick={() => setShowReviewModal(false)}>✕</button>
              <h3 className={styles.modalTitle}>Оставить отзыв о поездке</h3>
              <p className={styles.modalSubtitle}>Ваша оценка очень важна для улучшения качества обслуживания</p>
              
              <form onSubmit={handleReviewSubmit}>
                <div className={styles.modalField}>
                  <label>Рейтинг</label>
                  <div className={styles.starsContainer}>
                    {[1, 2, 3, 4, 5].map((star) => (
                      <span
                        key={star}
                        className={`${styles.star} ${(hoverRating || reviewRating) >= star ? styles.starFilled : ''}`}
                        onClick={() => setReviewRating(star)}
                        onMouseEnter={() => setHoverRating(star)}
                        onMouseLeave={() => setHoverRating(null)}
                      >
                        ★
                      </span>
                    ))}
                  </div>
                </div>

                <div className={styles.modalField}>
                  <label>Ваш комментарий</label>
                  <textarea 
                    className={styles.modalTextarea}
                    value={reviewComment}
                    onChange={(e) => setReviewComment(e.target.value)}
                    placeholder="Поделитесь впечатлениями о динамике автомобиля, комфорте и работе менеджера..."
                    rows={4}
                    required
                  />
                </div>

                <div className={styles.modalActions}>
                  <button type="button" className={styles.cancelBtn} onClick={() => setShowReviewModal(false)}>Отмена</button>
                  <button type="submit" className={styles.submitBtn}>Отправить отзыв</button>
                </div>
              </form>
            </motion.div>
          </motion.div>
        )}

        {/* 2. Модальное окно просмотра длинных комментариев */}
        {showViewModal && viewComment && (
          <motion.div 
            className={styles.modalOverlay}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => { setShowViewModal(false); setViewComment(null); }}
          >
            <motion.div
              className={styles.modal}
              initial={{ scale: 0.95, opacity: 0, y: 20 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              exit={{ scale: 0.95, opacity: 0, y: 20 }}
              transition={{ duration: 0.2 }}
              onClick={(e) => e.stopPropagation()}
            >
              <button className={styles.modalClose} onClick={() => { setShowViewModal(false); setViewComment(null); }}>✕</button>
              <h3 className={styles.modalTitle}>{viewComment.title}</h3>
              <p className={styles.modalSubtitle}>{viewComment.subtitle}</p>
              
              <div className={styles.modalField}>
                <div className={styles.commentContentBlock}>
                  {viewComment.comment}
                </div>
              </div>
              
              <div className={styles.modalActions}>
                <button 
                  type="button" 
                  className={styles.submitBtn} 
                  onClick={() => { setShowViewModal(false); setViewComment(null); }}
                >
                  Закрыть
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}

      </AnimatePresence>

      {/* ИЗОЛИРОВАННЫЙ БЛОК ДЛЯ СТРОГОЙ ИНДИВИДУАЛЬНОЙ ПЕЧАТИ ЧЕКА */}
      {purchases.map((purchase) => {
        if (purchase.id !== printingId) return null;
        return (
          <div key={`print-${purchase.id}`} className={styles.printOnlyReceiptContainer}>
            <div className={styles.receiptHeader}>
              <h2>LUXURY DEALER CO.</h2>
              <p>Официальный электронный чек купли-продажи транспортного средства</p>
            </div>
            
            <div className={styles.receiptDivider} />
            
            <div className={styles.receiptSection}>
              <h3>Информация о транзакции</h3>
              <p><strong>Номер договора/чека:</strong> #LD-PURCHASE-{purchase.id}-{purchase.car?.id}</p>
              <p><strong>Дата совершения операции:</strong> {new Date(purchase.created_at).toLocaleString()}</p>
              <p><strong>Статус платежа:</strong> Оплачено в полном объеме (АКЦЕПТОВАНO)</p>
            </div>

            <div className={styles.receiptSection}>
              <h3>Данные Покупателя</h3>
              <p><strong>ФИО клиента:</strong> {user?.full_name}</p>
              <p><strong>Номер телефона:</strong> {user?.phone}</p>
              <p><strong>Электронный адрес:</strong> {user?.email}</p>
            </div>

            <div className={styles.receiptSection}>
              <h3>Спецификация Автомобиля</h3>
              <table className={styles.receiptTable}>
                <thead>
                  <tr>
                    <th>Параметр</th>
                    <th>Значение</th>
                  </tr>
                </thead>
                <tbody>
                  <tr><td>Марка</td><td>{purchase.car?.brand}</td></tr>
                  <tr><td>Модель</td><td>{purchase.car?.model}</td></tr>
                  <tr><td>Год выпуска</td><td>{purchase.car?.year} г.</td></tr>
                  <tr><td>Тип кузова</td><td>{purchase.car?.body_type || 'Премиум седан/купе'}</td></tr>
                  <tr><td>Идентификатор авто в базе</td><td>ID {purchase.car?.id}</td></tr>
                </tbody>
              </table>
            </div>

            <div className={styles.receiptDivider} />

            <div className={styles.receiptTotal}>
              <span>ИТОГО К ОПЛАТЕ:</span>
              <span className={styles.totalSum}>{(purchase.price || purchase.car?.price)?.toLocaleString()} ₽</span>
            </div>

            <div className={styles.receiptFooter}>
              <p>Благодарим за покупку в автосалоне Luxury Dealer! Данный документ сформирован автоматически сервером и подтверждает переход права собственности в соответствии с правилами дилерского центра.</p>
              <div className={styles.signatures}>
                <div className={styles.sigLine}>М.П. Автосалон Luxury Dealer</div>
                <div className={styles.sigLine}>Подпись покупателя</div>
              </div>
            </div>
          </div>
        );
      })}

    </motion.div>
  );
};

export default UserDashboard;
